&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;egdcp-0-0&quot;&gt;&lt;span data-offset-key=&quot;egdcp-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Designing and implementing new features for Logstash and its plugins in Java and JRuby.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;9qjra&quot; data-offset-key=&quot;iiuq-0-0&quot;&gt;
