&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;de8or-0-0&quot;&gt;&lt;span data-offset-key=&quot;de8or-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;You&#39;ve built things with Elasticsearch before.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
