&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;3hlit-0-0&quot;&gt;&lt;span data-offset-key=&quot;3hlit-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;JRuby development&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
